                                                                                '      frobeniusSquared '
                                                                                '(A-A*(V*Matrix.diagonal '
                                                                                '(indicator '
                                                                                'S)*V.transpose))≤frobeniusSquared '
                                                                                '(A-B) := by\n'
                                                                                '  constructor\n'
                                                                                '  · exact '
                                                                                '(Matrix.rank_mul_le_right A '
                                                                                '_).trans '
                                                                                '(truncation_projection V S '
                                                                                'hv hvv).2.2.1\n'
                                                                                '  intro B hb\n'
                                                                                '  obtain '
                                                                                '⟨P,hs,hi,hBP,htrace⟩ := '
                                                                                'row_projection_exists B\n'
                                                                                '  let Q := V.transpose*P*V\n'
